// Stand-in for an installed test-utils package: registers mocks and endpoints for the calling file.
const endpoints = new Map()

/** Defines the global `name` as the result of `factory()` for the calling file. */
export function mockImport(name, factory) {
  globalThis[name] = factory()
}

/** Makes `fetch(url)` answer with `handler()`. */
export function registerEndpoint(url, handler) {
  endpoints.set(url, handler)
  globalThis.fetch = async (requested) => ({ json: async () => endpoints.get(requested)() })
}
